permuteHelperAST(
  metadata: HelperMetadata,
  id?: t.Identifier | t.MemberExpression,
  localBindings?: string[],
  getDependency?: GetDependency,
) {
  if (localBindings && !id) {
    throw new Error("Unexpected local bindings for module-based helpers.");
  }

  if (!id) return;

  const dependenciesRefs: Record<string, t.Expression> = {};
  metadata.dependencies.forEach((name, depId) => {
    dependenciesRefs[depId.name] =
      (typeof getDependency === "function" && getDependency(name)) || depId;
  });

  const toRename: Record<string, string> = {};
  const bindings = new Set(localBindings || []);
  metadata.localBindingNames.forEach(name => {
    let newName = name;
    while (bindings.has(newName)) newName = "_" + newName;

    if (newName !== name) toRename[name] = newName;
  });

  if (id.type === "Identifier" && metadata.exportName !== id.name) {
    toRename[metadata.exportName] = id.name;
  }

  const path = this.path;

  const exp: NodePath<t.ExportDefaultDeclaration> = path.get(
    metadata.exportPath,
  );
  const imps: NodePath<t.ImportDeclaration>[] = metadata.importPaths.map(p =>
    path.get(p),
  );
  const impsBindingRefs: NodePath<t.Identifier>[] =
    metadata.importBindingsReferences.map(p => path.get(p));

  const decl = exp.get("declaration") as NodePath<t.FunctionDeclaration>;

