      "body",
      expressionStatement(
        assignmentExpression("=", id, identifier(metadata.exportName)),
      ),
    );
  } else {
    throw new Error("Unexpected helper format.");
  }

  Object.keys(toRename).forEach(name => {
    this.scope.rename(name, toRename[name]);
  });

